using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Nexus.TaskManagement.Application;
using Nexus.TaskManagement.Application.Dtos;
using Nexus.TaskManagement.Domain;
using Nexus.TaskManagement.Infrastructure;

namespace Nexus.TaskManagement.Tests;

/// <summary>
/// Edit conflicts against real SQL Server, where the row version is generated by the database (CAT-209): the second
/// of two edits made from the same version is refused, and the first person's work stays.
/// </summary>
[Collection("sqlserver")]
public sealed class TaskConflictTests(SqlServerFixture fixture)
{
    private bool Skip => !fixture.Available;

    private CreateTaskRequest PlainTask(string title) =>
        new(title, new DateOnly(2026, 10, 1), AssignedUserId: fixture.OwnerUserId);

    private static UpdateTaskRequest Edit(TaskDto from, string title) =>
        new(title, from.DueDate, from.Priority, from.Description, AssignedUserId: from.AssignedUser?.Id, RowVersion: from.RowVersion);

    [Fact]
    public async Task TheSecondEditFromTheSameVersion_IsRefused_AndTheFirstEditStays()
    {
        if (Skip) return;

        var created = await fixture.ScopedAsync(sp => sp.GetRequiredService<ITaskService>().CreateAsync(PlainTask("Shared"), default));
        var read = (await fixture.ScopedAsync(sp => sp.GetRequiredService<ITaskService>().GetAsync(created.Value!.Id, default))).Value!;
        Assert.False(string.IsNullOrEmpty(read.RowVersion)); // the database hands out a version

        var first = await fixture.ScopedAsync(sp => sp.GetRequiredService<ITaskService>().UpdateAsync(read.Id, Edit(read, "First edit"), default));
        Assert.True(first.IsSuccess, first.IsFailure ? first.Error.Message : null);
        Assert.NotEqual(read.RowVersion, first.Value!.RowVersion); // every save moves it on

        var second = await fixture.ScopedAsync(sp => sp.GetRequiredService<ITaskService>().UpdateAsync(read.Id, Edit(read, "Second edit"), default));
        Assert.True(second.IsFailure);
        Assert.Equal("conflict", second.Error.Code);

        var now = (await fixture.ScopedAsync(sp => sp.GetRequiredService<ITaskService>().GetAsync(read.Id, default))).Value!;
        Assert.Equal("First edit", now.Title);

        // Reloaded, the edit goes through.
        var retry = await fixture.ScopedAsync(sp => sp.GetRequiredService<ITaskService>().UpdateAsync(read.Id, Edit(now, "Second edit"), default));
        Assert.True(retry.IsSuccess, retry.IsFailure ? retry.Error.Message : null);
    }

    [Fact]
    public async Task TwoSavesRacingOnTheSameRow_TheLaterOneIsRefusedByTheDatabase()
    {
        if (Skip) return;

        var created = await fixture.ScopedAsync(sp => sp.GetRequiredService<ITaskService>().CreateAsync(PlainTask("Racing"), default));
        var id = created.Value!.Id;

        // Both load the task before either saves: the second save finds the row already changed.
        var firstDone = new TaskCompletionSource();
        var secondLoaded = new TaskCompletionSource();
        var first = fixture.ScopedAsync(async sp =>
        {
            var task = await sp.GetRequiredService<ITaskRepository>().GetForUpdateAsync(fixture.TenantId, id, default);
            await secondLoaded.Task;
            task!.UpdateDetails("Racer one", null, task.DueDate, task.Priority, task.AssignedUserId, null, true);
            await sp.GetRequiredService<ITaskManagementUnitOfWork>().SaveChangesAsync(default);
            firstDone.SetResult();
        });
        var second = fixture.ScopedAsync(async sp =>
        {
            var task = await sp.GetRequiredService<ITaskRepository>().GetForUpdateAsync(fixture.TenantId, id, default);
            secondLoaded.SetResult();
            await firstDone.Task;
            task!.UpdateDetails("Racer two", null, task.DueDate, task.Priority, task.AssignedUserId, null, true);
            await Assert.ThrowsAsync<TaskConcurrencyException>(() => sp.GetRequiredService<ITaskManagementUnitOfWork>().SaveChangesAsync(default));
        });
        await Task.WhenAll(first, second);

        var title = await fixture.ScopedAsync(sp => sp.GetRequiredService<TaskManagementDbContext>().Tasks.Where(t => t.Id == id).Select(t => t.Title).SingleAsync());
        Assert.Equal("Racer one", title);
    }

    [Fact]
    public async Task AnArchivedTask_DoesNotGetRemindersOrReports_UntilRestored()
    {
        if (Skip) return;

        var created = await fixture.ScopedAsync(sp => sp.GetRequiredService<ITaskService>().CreateAsync(PlainTask("Archived reminder"), default));
        var id = created.Value!.Id;
        Assert.True((await fixture.ScopedAsync(sp => sp.GetRequiredService<ITaskService>().ArchiveAsync(id, default))).IsSuccess);

        var visible = await fixture.ScopedAsync(sp => sp.GetRequiredService<TaskManagementDbContext>().Tasks.AnyAsync(t => t.Id == id));
        Assert.False(visible);
        var kept = await fixture.ScopedAsync(sp => sp.GetRequiredService<TaskManagementDbContext>().Tasks.IgnoreQueryFilters().AnyAsync(t => t.Id == id && t.ArchivedAtUtc != null));
        Assert.True(kept);

        Assert.True((await fixture.ScopedAsync(sp => sp.GetRequiredService<ITaskService>().RestoreAsync(id, default))).IsSuccess);
        Assert.True(await fixture.ScopedAsync(sp => sp.GetRequiredService<TaskManagementDbContext>().Tasks.AnyAsync(t => t.Id == id)));
    }
}
